/**
 * @name SSRF via user-controlled URLs in HTTP requests
 * @description User-controlled data flowing to HTTP request functions can lead to SSRF attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module SsrfConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for various HTTP request functions
    exists(DataFlow::CallCfgNode call |
      sink = call.getArg(0) and
      (
        // requests library
        call = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "patch", "request"]).getACall() or
        // urllib/urllib2
        call = API::moduleImport("urllib.request").getMember(["urlopen", "Request"]).getACall() or
        call = API::moduleImport("urllib2").getMember(["urlopen", "Request"]).getACall() or
        // http.client
        call = API::moduleImport("http.client").getMember(["HTTPConnection", "HTTPSConnection"]).getACall() or
        // aiohttp
        call = API::moduleImport("aiohttp").getMember(["ClientSession"]).getACall() or
        // httpx
        call = API::moduleImport("httpx").getMember(["get", "post", "put", "delete", "head", "patch", "request"]).getACall()
      )
    )
  }
}

module SsrfFlow = TaintTracking::Global<SsrfConfig>;
import SsrfFlow::PathGraph

from SsrfFlow::PathNode source, SsrfFlow::PathNode sink
where SsrfFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF vulnerability: user-controlled data flows to HTTP request at $@.", source.getNode(), "user input"
